<script setup lang="ts">
import {ref,computed,reactive} from 'vue';
import ImageViewport from './ImageViewport.vue';
import MprViewport from './MprViewport.vue';
import PartViewport from './PartViewport.vue';
import VolumeViewport from './VolumeViewport.vue';
import AdvancedPanel from './AdvancedPanel.vue';
import LocalProjectsDialog from './LocalProjectsDialog.vue';
import ReplacementDialog from './ReplacementDialog.vue';
import Calculate3DDialog from './Calculate3DDialog.vue';
import LocalThresholdControls from './LocalThresholdControls.vue';
import MeasurementPropertiesDialog from './MeasurementPropertiesDialog.vue';
import ReslicePropertiesDialog from './ReslicePropertiesDialog.vue';
import ResliceProjectDialog from './ResliceProjectDialog.vue';
import STLCoordinateControls from './STLCoordinateControls.vue';
import {annotationDisplayText} from './annotationLayout.ts';
import {useWorkbench} from './useWorkbench.ts';
import {useDisplayMaskStatistics} from './displayMaskStatistics.ts';
import {physicalPoint,type Axis} from './types.ts';
import {direction,hasAnatomicalDirections} from '../view.ts';
import {isAxisAlignedGrid} from './viewportGeometry.ts';
import {partSourceStatus} from './partProvenance.ts';
import {measurementPartIds} from './measurementAttachments.ts';
import './workbench.css';
const props=defineProps<{editor?:ReturnType<typeof useWorkbench>;readOnly?:boolean;teamMode?:boolean;allowExport?:boolean}>();
const e=props.editor??useWorkbench();
const displayStats=useDisplayMaskStatistics(e.grid,e.activeMask,computed(()=>!!e.draft.value||!!e.mpr.brushPreview.value));
const maskInfo=displayStats.value;
const advanced=reactive(e.advanced);
const localThreshold=reactive(e.localThreshold);
const measurementEditor=reactive(e.measurementEditor);
const mpr=reactive(e.mpr);
const reslices=reactive(e.reslices);
const resliceProject=reactive(e.resliceProject);
const interactiveMprBindings=computed(()=>({interactivePlane:mpr.interactivePlane,interactiveCenter:mpr.interactiveCenter,interactiveEnabled:mpr.interactive,onTransformMpr:mpr.transform}));
const mprViewportBindings=computed(()=>({...interactiveMprBindings.value,activeMaskId:e.state.value.selectedMaskId,brushWidth:e.params.brushWidth,brushHeight:e.params.brushHeight,sameWidthHeight:e.params.sameWidthHeight,brushShape:e.params.brushShape as 'circle'|'square',brushPreview:mpr.brushPreview,brushPreviewRevision:mpr.brushPreviewRevision,onBeginBrush:mpr.beginBrush,onBrushStroke:mpr.brushStroke,onEndBrush:mpr.endBrush,onCancelBrush:mpr.cancelBrushGesture,contourDraft:mpr.contourDraft,contourSettingsKey:mpr.contourSettingsKey,onBeginContour:mpr.beginContour,onContourPoint:mpr.contourPoint,onPreviewContourPoint:mpr.previewContourPoint,onCompleteContour:mpr.completeContour,onCancelContour:mpr.cancelContourGesture,onResizeBrush:(size:{width:number;height:number})=>e.setBrushSize(size.width,size.height)}));
const resliceViewportBindings=computed(()=>({reslicePlane:reslices.selected?.plane,resliceId:e.state.value.selectedResliceId||'',resliceMode:mpr.resliceMode,resliceRevision:mpr.poseRevision,onUpdateReslicePlane:mpr.modifyPlane}));
const partPendingPoints=computed(()=>resliceProject.drawing?resliceProject.linePoints:mpr.defining?mpr.definitionPoints:!e.draftPlane.value&&!mpr.draftPlane&&e.grid.value?e.draftPoints.value.map(p=>physicalPoint(p,e.grid.value!)):[]);
const partOverlayLines=computed(()=>[...advanced.overlayLines,...resliceProject.lines]);
const imageReferenceLines=computed(()=>[...resliceProject.lines,...advanced.physicalPolylineLines]);
const {regionSourceId,regionSource}=e;
const {multipleEditing,imageTool,selectionAxis,displayMasks,interpolationPreview}=e;
const {displayMeasurements,selectedMeasurementDetails,measurementDraftToken}=e;
const {showCalculate3D,physicalUnitsKnown,spatialUnitChoice,renderMode,pendingReplacement,showLocalProjects,localProjects,cacheState,cacheError,volume,state,grid,point,activeAxis,tool,tab,objectTab,center,width,dirty,status,error,busy,progress,preview,selection,draft,draftRevision,draftPoints,draftPlane,params,series,seriesChoice,activeMask,activePart,partInfo,undoName,redoName,measurementLabels,revision,imageMeta,selectedMeasurementId}=e;
const fileInput=ref<HTMLInputElement>(),folderInput=ref<HTMLInputElement>(),maskInput=ref<HTMLInputElement>(),stlInput=ref<HTMLInputElement>();
const axes:Axis[]=[2,1,0];
const segmentTools=[{id:'navigate',name:'定位',icon:'⌖'},{id:'threshold',name:'阈值',icon:'◩'},{id:'region',name:'区域生长',icon:'✣'},{id:'dynamic',name:'动态增长',icon:'✺'},{id:'paint',name:'绘制',icon:'✎'},{id:'erase',name:'擦除',icon:'▱'},{id:'local-threshold',name:'局部阈值',icon:'◈'},{id:'lasso',name:'闭合轮廓',icon:'◇'},{id:'livewire',name:'LiveWire',icon:'⌁'},{id:'multiple',name:'多片编辑',icon:'▤'},{id:'boolean',name:'布尔运算',icon:'◒'},{id:'morphology',name:'形态学',icon:'▦'},{id:'cavity',name:'填充腔体',icon:'◉'},{id:'fill',name:'填充孔洞',icon:'⊙'},{id:'largest',name:'最大连通域',icon:'▣'},{id:'smartExpand',name:'Smart Expand',icon:'✧'},{id:'crop',name:'裁剪Mask',icon:'⌗'}];
const measurementTools=[{id:'distance',name:'距离',icon:'↔'},{id:'angle',name:'角度',icon:'∠'},{id:'diameter',name:'三点直径',icon:'⌀'},{id:'ellipse',name:'椭圆',icon:'⬭'},{id:'area',name:'多边形面积',icon:'⬠'},{id:'density-rectangle',name:'矩形密度',icon:'▭'},{id:'density-ellipse',name:'椭圆密度',icon:'◯'},{id:'annotation',name:'文字标注',icon:'T'},{id:'surface-distance',name:'曲面路径',icon:'⌁'}];
const tools=computed(()=>tab.value==='measurements'?measurementTools:segmentTools);
const toolName=computed(()=>tool.value==='mpr-plane'?'三点定义重切片平面':[...segmentTools,...measurementTools].find(t=>t.id===tool.value)?.name||'多片编辑');
const histogram=computed(()=>{if(!volume.value)return[];const v=volume.value,bins=new Uint32Array(96),span=v.max-v.min||1;for(const x of v.data)if(Number.isFinite(x))bins[Math.max(0,Math.min(95,Math.floor((x-v.min)/span*95)))]++;const max=Math.max(...bins)||1;return Array.from(bins,x=>Math.log1p(x)/Math.log1p(max)*68);});
const pendingSelection=multipleEditing;
const contourTool=computed(()=>['lasso','livewire'].includes(tool.value));
const densityTool=computed(()=>['density-rectangle','density-ellipse'].includes(tool.value));
const densitySize=computed<[number,number]>(()=>[params.densityWidth,params.densityHeight]);
const brushSettings=computed(()=>['paint','erase','local-threshold'].includes(tool.value)||(multipleEditing.value&&params.selectionType==='brush'));
const editOperationName=computed(()=>params.editOperation==='remove'?'Erase · 擦除':params.editOperation==='threshold'?'Threshold · 局部阈值':'Draw · 绘制');
const displayPreview=computed(()=>preview.value);
const temporaryPreview=computed(()=>multipleEditing.value?interpolationPreview.value||draft.value||selection.value:null);
const selectionCount=computed(()=>selection.value?.reduce((s,v)=>s+(v?1:0),0)||0);
const partSourceWarning=computed(()=>{if(!activePart.value)return'';const source=partSourceStatus(activePart.value,state.value.masks);return source==='missing'?'源 Mask 已删除；此模型保留了计算时的历史几何。':source==='unknown'?'来源 Mask 的计算版本未知，无法判断此模型是否同步。':source==='stale'?'源 Mask 已修改；此模型保留了计算时的几何，可重新计算3D。':'';});
function switchTab(next:string){tab.value=next;tool.value=next==='measurements'?'distance':next==='surface'?'navigate':'navigate';}
function chooseTool(id:string){mpr.endPlaneModify();const mprBrush=['paint','erase','local-threshold','lasso','livewire'].includes(id);if(mprBrush)mpr.stopInteractive();if(!['navigate','distance','angle','diameter','ellipse','area','density-rectangle','density-ellipse','annotation','surface-distance','paint','erase','local-threshold','lasso','livewire'].includes(id)){mpr.stopInteractive();if(mpr.enabled)mpr.close();}tool.value=id;}
function changeMprStep(event:Event){const input=event.target as HTMLInputElement;mpr.setStep(Number(input.value));input.value=String(mpr.step);}
function fileChange(event:Event){const el=event.target as HTMLInputElement;void e.openFiles(el.files);el.value='';}
function editName(event:Event,id:string){e.updateMask(id,{name:(event.target as HTMLInputElement).value});}
function format(n?:number|null){return n===undefined||n===null?'—':n.toLocaleString(undefined,{maximumFractionDigits:2});}
const selectedMeasurement=computed(()=>state.value.measurements.find(m=>m.id===selectedMeasurementId.value));
function measurementValue(value:unknown,unit=''):string{
  if(Array.isArray(value))return value.map(n=>measurementValue(n)).join(', ')+(unit?' '+unit:'');
  return typeof value==='number'&&Number.isFinite(value)?value.toLocaleString(undefined,{maximumFractionDigits:4})+(unit?' '+unit:''):'—';
}
const measurementRows=computed(()=>{
  const result=selectedMeasurementDetails.value;if(!result)return[];const d=result.details,rows:{label:string;value:string}[]=[];
  const add=(label:string,value:unknown,unit='')=>rows.push({label,value:measurementValue(value,unit)});
  if(result.kind.startsWith('density')){
    add('Mean · 平均值',d.mean,result.unit);add('SD · 标准差',d.std,result.unit);add('Min · 最小值',d.min,result.unit);add('Max · 最大值',d.max,result.unit);add('有效采样数',d.count);add('排除采样数',d.excluded);add('采样覆盖面积',d.sampleArea,'mm²');add('ROI 几何面积',d.geometricArea,'mm²');
  }else if(result.kind==='ellipse'){
    for(const [key,label,unit] of [['D1','D1 · 长径','mm'],['D2','D2 · 短径','mm'],['E','E · 离心率',''],['P','P · 周长','mm'],['A','A · 面积','mm²'],['DP','DP · 周长等效直径','mm'],['DA','DA · 面积等效直径','mm']] as const)add(label,d[key],unit);
    add('Center · 中心世界坐标',d.center,'mm');
  }else if(result.kind==='area'){
    add('A · 面积',d.area,'mm²');add('P · 周长',d.perimeter,'mm');add('Da · 面积等效直径',d.Da,'mm');add('Dp · 周长等效直径',d.Dp,'mm');add('Lmax · 过质心最长弦',d.Lmax,'mm');add('L · 垂直方向弦长',d.L,'mm');add('Centroid · 质心世界坐标',d.centroid,'mm');
  }else{add(result.kind==='angle'?'Angle · 角度':result.kind==='diameter'?'Diameter · 直径':'Length · 长度',result.value,result.unit==='degree'?'°':result.unit);if(result.kind==='diameter'){add('Radius · 半径',d.radius,'mm');add('Center · 圆心世界坐标',d.center,'mm');}}
  return rows;
});
function planeOptions(){return params.multiple?{}:{plane:{axis:activeAxis.value,index:point.value[activeAxis.value]}};}
function cancelImageInteraction(){if(['lasso','livewire'].includes(imageTool.value))e.cancel();else e.brushCancel();}
function viewportTool(axis:Axis){return multipleEditing.value&&axis!==selectionAxis.value?'navigate':imageTool.value;}
function selectionDirection(axis:Axis){if(!volume.value||!grid.value||!hasAnatomicalDirections(volume.value)||!volume.value.niftiReference&&!isAxisAlignedGrid(grid.value))return `${['I','J','K'][axis]} 轴 · 原始切片`;return `${direction(volume.value,axis)} (${['I','J','K'][axis]})`;}
function changeBrushDimension(dimension:'width'|'height',event:Event){const input=event.target as HTMLInputElement,value=Number(input.value);e.setBrushSize(dimension==='width'?value:params.brushWidth,dimension==='height'?value:params.brushHeight);input.value=String(dimension==='width'?params.brushWidth:params.brushHeight);}
</script>
<template>
  <div class="mimics-workbench" :data-shared="!!props?.teamMode" :data-readonly="!!props?.readOnly">
    <slot v-if="props?.editor" name="collaboration"/>
    <header class="mw-topbar">
      <div class="mw-brand"><span class="mw-brandmark">◈</span><div>Deepmark <b>Studio</b><small>影像 · 分割 · 三维重建</small></div></div>
      <div class="mw-project-name"><strong>{{volume?state.name:'未打开工程'}}</strong><span v-if="volume">{{volume.dims.join(' × ')}} · {{volume.spacing.map(x=>x.toFixed(2)).join(' / ')}} {{volume.unit}}</span><i v-if="dirty" title="有未保存的修改"/></div>
      <div class="mw-actions"><button @click="e.openLocalProjects">本地工程</button><button :disabled="props?.readOnly||(busy)" @click="fileInput?.click()">打开影像 / 工程</button><button :disabled="props?.readOnly||(busy)" @click="folderInput?.click()">DICOM 文件夹</button><button :disabled="props?.readOnly||(!volume||busy||!physicalUnitsKnown)" @click="resliceProject.show">Reslice Project…</button><button :disabled="(props?.teamMode&&!props?.allowExport)||(!volume||busy)" class="mw-primary" @click="e.saveProject">保存工程</button><button :disabled="(props?.teamMode&&!props?.allowExport)||(!volume||busy)" @click="e.downloadProject">下载工程副本</button><a v-if="!props?.teamMode" href="?workspace=collaboration" title="打开原有协作标注工作台">协作工作台 ↗</a></div>
    </header>
    <input ref="fileInput" class="mw-hidden" type="file" multiple accept=".nii,.nii.gz,.dcm,.zip" @change="fileChange"><input ref="folderInput" class="mw-hidden" type="file" multiple webkitdirectory @change="fileChange"><input ref="maskInput" class="mw-hidden" type="file" accept=".nii,.nii.gz" @change="e.importMask(($event.target as HTMLInputElement).files?.[0]);($event.target as HTMLInputElement).value='' "><input ref="stlInput" class="mw-hidden" type="file" accept=".stl" @change="e.importStl(($event.target as HTMLInputElement).files?.[0]);($event.target as HTMLInputElement).value='' ">
    <nav class="mw-ribbon"><div class="mw-tabs"><button :class="{active:tab==='segmentation'}" @click="switchTab('segmentation')">分割与标注</button><button :class="{active:tab==='surface'}" @click="switchTab('surface')">三维重建</button><button :class="{active:tab==='measurements'}" @click="switchTab('measurements')">测量与注释</button><button :class="{active:tab==='analysis'}" @click="switchTab('analysis')">轮廓与中心线</button></div><div class="mw-history"><button :disabled="props?.readOnly||(!undoName||busy)" :title="undoName" @click="e.undo()">↶ 撤销</button><button :disabled="props?.readOnly||(!redoName||busy)" :title="redoName" @click="e.undo(true)">↷ 重做</button></div></nav>
    <div v-if="series.length" class="mw-series"><label>检测到多个 DICOM 系列<select v-model.number="seriesChoice" :disabled="busy"><option v-for="(s,i) in series" :key="s.seriesInstanceUID" :value="i">{{s.modality}} · {{s.slices.length}} 张 · 系列 {{i+1}}</option></select></label><button :disabled="props?.readOnly||(busy)" @click="e.loadSeries">加载所选系列</button></div>
    <div v-if="volume&&!physicalUnitsKnown" class="mw-unit-notice"><span>影像没有声明空间单位。请按影像来源确认，之后再进行物理尺寸标注和3D计算。</span><select v-model.number="spatialUnitChoice" aria-label="影像原始空间单位"><option :value="2">毫米 mm</option><option :value="1">米 m</option><option :value="3">微米 µm</option></select><button :disabled="props?.readOnly||(busy)" @click="e.confirmSpatialUnit">确认空间单位</button></div>
    <div class="mw-layout">
      <aside class="mw-objects">
        <div class="mw-panel-title">工程对象<span>{{state.masks.length+state.parts.length+state.measurements.length+(state.centerlines?.length||0)+(state.polylines?.length||0)+reslices.objects.length}}</span></div>
        <div class="mw-object-tabs"><button :class="{active:objectTab==='masks'}" @click="objectTab='masks'">Mask {{state.masks.length}}</button><button :class="{active:objectTab==='parts'}" @click="objectTab='parts'">3D {{state.parts.length}}</button><button :class="{active:objectTab==='measurements'}" @click="objectTab='measurements'">测量 {{state.measurements.length}}</button><button :class="{active:objectTab==='reslices'}" @click="objectTab='reslices'">RP {{reslices.objects.length}}</button><button :class="{active:objectTab==='curves'}" @click="objectTab='curves'">曲线 {{(state.centerlines?.length||0)+(state.polylines?.length||0)}}</button></div>
        <div v-if="objectTab==='masks'" class="mw-object-body">
          <div class="mw-object-controls"><button :disabled="props?.readOnly||(!volume||busy)" @click="e.newMask">＋ 新建</button><button :disabled="props?.readOnly||(!activeMask||busy)" @click="e.duplicateMask">复制</button><button :disabled="props?.readOnly||(!activeMask||busy)" @click="e.deleteMask">删除</button></div>
          <div v-for="mask in state.masks" :key="mask.id" :class="['mw-mask-row',{selected:mask.id===state.selectedMaskId}]" @click="!busy&&e.selectMask(mask.id)"><input :aria-label="mask.name+'颜色'" type="color" :value="mask.color" :disabled="props?.readOnly||busy" @change="e.updateMask(mask.id,{color:($event.target as HTMLInputElement).value})"><div><input :aria-label="mask.id+'名称'" :value="mask.name" :disabled="props?.readOnly||busy" @change="editName($event,mask.id)"><small>{{mask.threshold?mask.threshold.join(' ~ '):'独立分割Mask'}} · r{{mask.revision}}</small></div><button :aria-label="mask.visible?'隐藏Mask':'显示Mask'" :disabled="props?.readOnly||(busy)" @click.stop="e.updateMask(mask.id,{visible:!mask.visible})">{{mask.visible?'◉':'○'}}</button></div>
          <div v-if="activeMask" class="mw-object-properties" :data-mask-statistics-pending="displayStats?.pending?.value" :aria-busy="displayStats?.pending?.value"><label>透明度 <span>{{Math.round(activeMask.opacity*100)}}%</span><input type="range" min="0" max="1" step=".05" :value="activeMask.opacity" :disabled="busy" @change="e.updateMask(activeMask.id,{opacity:Number(($event.target as HTMLInputElement).value)})"></label><dl v-if="maskInfo"><dt>体素</dt><dd>{{format(maskInfo.count)}}</dd><dt>体积</dt><dd>{{format(maskInfo.volumeMm3)}} {{physicalUnitsKnown?'mm³':'影像单位³'}}</dd><dt>灰度均值</dt><dd>{{format(maskInfo.mean)}}</dd></dl><button :disabled="props?.readOnly||(busy)" @click="e.clearMask">清空成员，保留阈值</button></div>
          <p v-if="!state.masks.length" class="mw-hint">加载影像后创建 Mask。每个 Mask 独立保存，可以相互重叠。</p>
          <div class="mw-bottom-buttons"><button :disabled="props?.readOnly||(!volume||busy)" @click="maskInput?.click()">导入 Mask</button><button :disabled="(props?.teamMode&&!props?.allowExport)||(!activeMask||busy)" @click="e.exportMask">导出 NIfTI</button><button :disabled="(props?.teamMode&&!props?.allowExport)||(!activeMask||busy)" @click="e.downloadMask">下载 NIfTI 副本</button></div>
        </div>
        <div v-else-if="objectTab==='parts'" class="mw-object-body"><STLCoordinateControls :frame="params.stlFrame" :has-reference="!!volume?.niftiReference" :busy="busy" @change="e.setStlFrame"/><div class="mw-object-controls"><button :disabled="props?.readOnly||(!volume||busy)" @click="stlInput?.click()">导入 STL</button><button :disabled="props?.readOnly||(!activePart||busy)" @click="e.deletePart">删除</button></div><div v-for="part in state.parts" :key="part.id" :class="['mw-part-row',{selected:part.id===state.selectedPartId}]" @click="!busy&&e.selectPart(part.id)"><span :style="{color:part.color}">◆</span><div><strong>{{part.name}}</strong><small>{{format(part.mesh.indices.length/3)}} triangles</small></div><button :disabled="props?.readOnly||(busy)" @click.stop="e.togglePart(part.id)">{{part.visible?'◉':'○'}}</button></div><div v-if="partInfo&&activePart" class="mw-object-properties"><label>颜色<input type="color" :value="activePart.color" :disabled="props?.readOnly||busy" @change="e.updatePart(activePart.id,{color:($event.target as HTMLInputElement).value})"></label><label>透明度<input type="range" min="0" max="1" step=".05" :value="activePart.opacity" :disabled="busy" @change="e.updatePart(activePart.id,{opacity:Number(($event.target as HTMLInputElement).value)})"></label><dl><dt>表面积</dt><dd>{{format(partInfo.area)}} mm²</dd><dt>网格体积</dt><dd>{{partInfo.closed?format(partInfo.volume):'未闭合'}} mm³</dd><dt>开放边</dt><dd>{{partInfo.boundaryEdges}}</dd><dt>非流形边</dt><dd>{{partInfo.nonManifoldEdges}}</dd><dt>连通分量</dt><dd>{{partInfo.components}}</dd></dl><p v-if="partSourceWarning" class="mw-hint mw-warning">{{partSourceWarning}}</p></div><p v-if="!state.parts.length" class="mw-hint">从 Mask 计算三维表面，或导入 STL。网格后处理不会自动修改源 Mask。</p><button :disabled="(props?.teamMode&&!props?.allowExport)||(!activePart||busy)" class="mw-primary" @click="e.exportPart">导出二进制 STL</button><button :disabled="(props?.teamMode&&!props?.allowExport)||(!activePart||busy)" @click="e.downloadPart">下载 STL 副本</button></div>
        <div v-else-if="objectTab==='measurements'" class="mw-object-body"><div v-for="m in state.measurements" :key="m.id" class="mw-measure-row" @click="selectedMeasurementId=m.id"><strong>{{m.name}}</strong><span :title="m.kind==='annotation'?m.text||m.name:measurementLabels[m.id]">{{m.kind==='annotation'?annotationDisplayText(m.text||m.name,180):measurementLabels[m.id]}}</span><small v-if="measurementPartIds(m).some(id=>!state.parts.some(p=>p.id===id))">来源模型已删除 · 保留世界坐标</small><button :disabled="props?.readOnly||(busy)" @click.stop="measurementEditor.openEdit(m.id)">Properties · 属性</button><button :disabled="props?.readOnly||(busy)" @click.stop="measurementEditor.duplicate(m.id)">Duplicate · 复制</button><button :disabled="props?.readOnly||(busy)" @click.stop="measurementEditor.toggle(m.id)">{{m.visible?'Hide · 隐藏':'Show · 显示'}}</button><button :disabled="props?.readOnly||(busy)" @click.stop="e.locateMeasurement(m.id)">Locate · 定位</button><button :disabled="props?.readOnly||(busy)" @click.stop="e.deleteMeasurement(m.id)">Delete · 删除</button></div><p v-if="!state.measurements.length" class="mw-hint">在切片或三维表面上放置测量点。选择注释锚点后在 Properties 中编辑文字；注释独立于 Mask 保存。</p></div>
        <div v-else-if="objectTab==='reslices'" class="mw-object-body">
          <div class="mw-object-controls"><button :disabled="props?.readOnly||(!volume||busy||!physicalUnitsKnown)" @click="mpr.beginDefinition">New · 三点 RP</button><button :disabled="props?.readOnly||(!volume||busy||!physicalUnitsKnown)" @click="mpr.startInteractive">New · 交互 RP</button></div>
          <div v-for="object in reslices.objects" :key="object.id" :class="['mw-reslice-row',{selected:object.id===state.selectedResliceId}]" @click="!busy&&reslices.select(object.id)">
            <div class="mw-reslice-title"><button :disabled="props?.readOnly||(busy)" :aria-label="'激活重切片 '+object.name" :title="object.id===state.selectedResliceId?'当前活动重切片':'激活此重切片'" @click.stop="reslices.select(object.id)">{{object.id===state.selectedResliceId?'◉':'○'}}</button><input :value="object.name" :aria-label="object.id+'名称'" :disabled="props?.readOnly||busy" @click.stop @change="reslices.rename(object.id,($event.target as HTMLInputElement).value)"></div>
            <small>{{format(object.plane.size[0]*Math.hypot(...object.plane.u))}} × {{format(object.plane.size[1]*Math.hypot(...object.plane.v))}} mm</small>
            <div class="mw-reslice-actions"><button :disabled="props?.readOnly||(busy)" @click.stop="reslices.openProperties(object.id)">Properties · 属性</button><button :disabled="props?.readOnly||(busy)" @click.stop="reslices.duplicate(object.id)">Duplicate · 复制</button><button :disabled="props?.readOnly||(busy)" @click.stop="mpr.editInteractive(object.id)">交互编辑</button><button :disabled="props?.readOnly||(busy)" @click.stop="mpr.beginPlaneModify('rotate',object.id)">Rotate · 旋转</button><button :disabled="props?.readOnly||(busy)" @click.stop="mpr.beginPlaneModify('resize',object.id)">Resize · 调整边框</button><button :disabled="props?.readOnly||(busy)" @click.stop="reslices.remove(object.id)">Delete · 删除</button></div>
          </div>
          <p v-if="!reslices.objects.length" class="mw-hint">三点定义或交互式 MPR 会创建独立的 RP 平面。活动 RP 的图像显示在重切片布局中。</p>
        </div>
        <div v-else class="mw-object-body"><div v-for="o in advanced.centerlines" :key="o.id" class="mw-measure-row" @click="advanced.selectCenterline(o.id)"><strong>{{o.name}}</strong><span>{{o.graph.branches.length}} 个分支</span><button :disabled="props?.readOnly||(busy)" @click.stop="advanced.toggleCurve(o.id,'centerline')">{{o.visible?'隐藏':'显示'}}</button><button :disabled="props?.readOnly||(busy)" @click.stop="advanced.deleteCurve(o.id,'centerline')">删除</button></div><div v-for="o in advanced.polylines" :key="o.id" class="mw-measure-row" @click="advanced.selectPolyline(o.id)"><strong>{{o.name}}</strong><span>{{o.set.layers.length}} 层轮廓</span><button :disabled="props?.readOnly||(busy)" @click.stop="advanced.toggleCurve(o.id,'polyline')">{{o.visible?'隐藏':'显示'}}</button><button :disabled="props?.readOnly||(busy)" @click.stop="advanced.deleteCurve(o.id,'polyline')">删除</button></div></div>
        <div class="mw-window"><div class="mw-panel-title">窗宽窗位</div><div class="mw-two"><label>窗位<input v-model.number="center" type="number" :disabled="!volume"></label><label>窗宽<input v-model.number="width" type="number" min="1" :disabled="!volume"></label></div><div class="mw-presets"><button @click="center=400;width=1800">骨窗</button><button @click="center=40;width=400">软组织</button><button @click="center=-600;width=1500">肺窗</button></div></div>
      </aside>
      <main class="mw-view-area">
        <div v-if="volume&&grid" class="mw-view-grid">
          <template v-if="!mpr.enabled">
          <ImageViewport v-for="axis in axes" :key="axis" :reference-lines="imageReferenceLines" :reference-point-token="resliceProject.lineToken" @reference-point="resliceProject.addLinePoint" v-bind="interactiveMprBindings" :mpr-revision="mpr.poseRevision" :volume="volume" :grid="grid" :display-inverted="imageMeta?.displayInverted" :intensity-unit="imageMeta?.intensityUnit" :axis="axis" :point="point" :masks="displayMasks" :revision="revision" :center="center" :width="width" :tool="viewportTool(axis)" :diameter="params.diameter" :density-size="densitySize" @create-density-r-o-i="e.createDensityROI" @update-measurement-geometry="e.updateMeasurementGeometry" @update-measurement-label="e.updateMeasurementLabel" @preview-measurement-geometry="e.previewMeasurementGeometry" :brush-width="params.brushWidth" :brush-height="params.brushHeight" :same-width-height="params.sameWidthHeight" @resize-brush="e.setBrushSize($event.width,$event.height)" :preview="displayPreview" :temporary-selection="temporaryPreview" :preview-replaces-active="!!preview" :draft="pendingSelection?null:draft" :draft-revision="draftRevision" :draft-bounds="e.draftBounds?.value" :active-mask-id="state.selectedMaskId" :measurements="displayMeasurements" :measurement-labels="measurementLabels" :draft-points="draftPoints" :draft-plane="draftPlane" :brush-shape="params.brushShape" :allow-edit="!props?.readOnly&&(!busy&&(!multipleEditing||axis===selectionAxis)&&!interpolationPreview)" @cancel="cancelImageInteraction" @point="point=$event" @begin="e.brushBegin" @stroke="e.brushStroke" @end="e.brushEnd" @pick="e.imagePick" @complete="e.finishDrawing" @activate="activeAxis=$event" @edit-measurement="measurementEditor.openEdit" @move-measurement-point="e.moveMeasurementPoint"/>
          </template>
          <template v-else>
            <MprViewport v-for="(plane,index) in mpr.planes" :key="index" :reference-lines="imageReferenceLines" :reference-point-token="resliceProject.lineToken" @reference-point="resliceProject.addLinePoint" v-bind="mprViewportBindings" :view-id="index" :volume="volume" :grid="grid" :plane="plane" :step="mpr.step" :interpolation="mpr.interpolation" :revision="revision" :mpr-revision="mpr.poseRevision" :point="point" :crosshair="mpr.crosshair||undefined" :tool="tool" :center="center" :width="width" :masks="state.masks" :measurements="mpr.displayMeasurements" :measurement-labels="measurementLabels" :allow-edit="!props?.readOnly&&(!busy||mpr.contourPending)" :density-size="densitySize" :draft-points="mpr.draftPoints" :draft-plane="mpr.draftPlane" :display-inverted="imageMeta?.displayInverted" :intensity-unit="imageMeta?.intensityUnit" @point="mpr.locate($event)" @scroll="mpr.scroll" @pick="mpr.pick" @complete="e.finishDrawing" @cancel="e.cancel" @edit-measurement="measurementEditor.openEdit" @move-measurement-point="mpr.moveMeasurementPoint" @update-measurement-geometry="mpr.updateMeasurementGeometry" @preview-measurement-geometry="mpr.previewMeasurementGeometry" @update-measurement-label="mpr.updateMeasurementLabel" @create-density-r-o-i="mpr.createDensityROI"/>
          </template>
          <div class="mw-three-dock"><div class="mw-render-tabs"><button :class="{active:renderMode==='parts'}" @click="renderMode='parts'">表面模型</button><button :class="{active:renderMode==='volume'}" @click="renderMode='volume'">体绘制</button></div>
            <PartViewport v-bind="resliceViewportBindings" :volume="volume" :tool="tool" :allow-edit="!props?.readOnly&&(!busy)" :spatial-unit="volume.unit" v-if="renderMode==='parts'" :reference-point-token="resliceProject.lineToken" @reference-point="resliceProject.addLinePoint" :overlay-lines="partOverlayLines" :parts="state.parts" :revision="revision" :selected-id="state.selectedPartId" :measurements="displayMeasurements" :measurement-labels="measurementLabels" :pending-points="partPendingPoints" :measurement-draft-token="measurementDraftToken" :selected-measurement-id="selectedMeasurementId" @select-measurement="selectedMeasurementId=$event;objectTab='measurements'" @edit-measurement="measurementEditor.openEdit" @move-measurement-point="e.moveMeasurementPoint" @update-measurement-geometry="e.updateMeasurementGeometry" @update-measurement-label="e.updateMeasurementLabel" @preview-measurement-geometry="e.previewMeasurementGeometry" @complete-ellipse-creation="e.completeEllipseCreation" @select="e.selectPart" @pick="e.partPick"/>
            <VolumeViewport v-else :spatial-unit="volume.unit" :intensity-unit="imageMeta?.intensityUnit" :grid="grid" :window-center="center" :window-width="width" preset="both"/>
          </div>
        </div>
        <div v-else class="mw-welcome"><div class="mw-welcome-mark">◈</div><span>IMAGE TO GEOMETRY</span><h1>从影像建立三维模型</h1><p>独立 Mask 分割 · 三视图联动 · 表面重建 · 几何测量</p><div><button class="mw-primary" @click="fileInput?.click()">打开影像或工程</button><button @click="e.demo()">加载合成练习影像</button><button @click="e.demo('vessel')">合成血管</button></div><small>NIfTI / 未压缩 DICOM 系列 / Deepmark 工程 ZIP</small><div class="mw-workflow-steps"><span>01<em>影像与空间</em></span><i>→</i><span>02<em>分割与编辑</em></span><i>→</i><span>03<em>三维表面</em></span><i>→</i><span>04<em>测量与导出</em></span></div></div>
        <div v-if="preview" class="mw-preview-banner">预览尚未修改 Mask<button :disabled="props?.readOnly||(busy)" @click="e.applyPreview">应用预览</button><button @click="preview=null">取消预览</button></div>
        <div v-if="busy" class="mw-computing"><span class="mw-spinner"/><div>正在计算<span>{{progress?Math.round(progress*100)+'%':'后台处理'}}</span><progress max="1" :value="progress||undefined"/></div><button @click="e.cancel">取消</button></div>
      </main>
      <aside class="mw-inspector">
        <section v-if="reslices.selected" class="mw-rp-modify-controls" aria-label="三维重切片平面修改"><div class="mw-panel-title">{{reslices.selected.name}} · 三维平面</div><div class="mw-two"><button :class="{active:mpr.resliceMode==='rotate'}" :disabled="props?.readOnly||(busy)" @click="mpr.beginPlaneModify('rotate',reslices.selected.id)">Rotate · 旋转/移动</button><button :class="{active:mpr.resliceMode==='resize'}" :disabled="props?.readOnly||(busy)" @click="mpr.beginPlaneModify('resize',reslices.selected.id)">Resize · 调整边框</button></div><p v-if="mpr.resliceMode==='rotate'" class="mw-hint">在三维视图拖中心平移、拖四角绕平面法线旋转；其他方向可在 Properties 中调整。</p><p v-if="mpr.resliceMode==='resize'" class="mw-hint">拖红色边角对称调整毫米范围，采样点数保持不变；拖中心平移。</p><button v-if="mpr.resliceMode!=='view'" :disabled="props?.readOnly||(busy)" @click="mpr.endPlaneModify">结束平面修改</button><button :disabled="props?.readOnly||(busy)" @click="reslices.openProperties(reslices.selected.id)">Plane Properties · 平面属性</button><div class="mw-divider"/></section>
        <div v-if="volume" class="mw-interactive-mpr-controls"><button :class="{active:mpr.interactive}" :disabled="props?.readOnly||(busy||!physicalUnitsKnown)" @click="mpr.interactive?mpr.stopInteractive():mpr.startInteractive()">{{mpr.interactive?'停止蓝轴交互':'交互式 MPR · 新建 RP'}}</button><p v-if="mpr.interactive" class="mw-hint">按住 Ctrl，拖蓝色中心平移，拖蓝色轴线旋转。蓝轴属于活动 RP；普通定位和滚片不会移动它。松开后保存一次，可撤销。</p></div>
        <section v-if="volume" class="mw-mpr-controls" aria-label="在线 MPR 重切片"><div class="mw-panel-title">Online Reslice · 在线重切片</div><div class="mw-two"><button :disabled="props?.readOnly||(busy||!physicalUnitsKnown)" @click="mpr.enabled?mpr.close():mpr.open()">{{mpr.enabled?'返回原始三视图':'显示 MPR 三正交视图'}}</button><button :disabled="props?.readOnly||(busy||!physicalUnitsKnown)" @click="mpr.beginDefinition">三点定义平面</button></div><template v-if="mpr.defining"><p class="mw-hint">在影像或三维表面上指定三个不同且不共线的点。已指定 {{mpr.definitionPoints.length}} / 3；Escape 取消。</p><button @click="e.cancel">取消平面定义</button></template><template v-if="mpr.enabled"><div class="mw-mpr-presets"><button :disabled="props?.readOnly||(busy)" @click="mpr.preset('axial')">轴位</button><button :disabled="props?.readOnly||(busy)" @click="mpr.preset('coronal')">冠状</button><button :disabled="props?.readOnly||(busy)" @click="mpr.preset('sagittal')">矢状</button></div><div class="mw-mpr-angles"><label v-for="(axis,i) in ['X','Y','Z']" :key="axis">绕 {{axis}} (°)<input v-model.number="mpr.rotation[i]" type="number" step="1" :disabled="busy"></label></div><div class="mw-two"><label>宽度 (samples)<input v-model.number="mpr.resolution[0]" type="number" min="1" max="2048" :disabled="busy"></label><label>高度 (samples)<input v-model.number="mpr.resolution[1]" type="number" min="1" max="2048" :disabled="busy"></label></div><button :disabled="props?.readOnly||(busy)" @click="mpr.applyOrientation">应用方向与采样尺寸</button><div class="mw-two"><label>法向层间距 (mm)<input :value="mpr.step" type="number" min=".001" step=".1" :disabled="busy" @change="changeMprStep"></label><label>灰度采样<select :value="mpr.interpolation" :disabled="busy" @change="mpr.setInterpolation(($event.target as HTMLSelectElement).value as 'linear'|'nearest')"><option value="linear">三线性</option><option value="nearest">最近邻</option></select></label></div><button :disabled="props?.readOnly||(!mpr.crosshair||busy)" @click="mpr.syncToSource">将 MPR 定位同步到原始三视图</button><p class="mw-hint">滚轮沿各自法线翻片，Ctrl＋滚轮缩放，右拖平移。MPR 定位与原始三视图独立；灰度采样不修改影像，Mask 使用最近邻显示。</p><p class="mw-hint">支持测量、文字、画笔及 Lasso/LiveWire。Lasso 松开闭合；LiveWire 点选锚点，Enter/双击闭合（本应用约定）；Escape 取消。多片编辑仍在原始切片操作。</p></template><div class="mw-divider"/></section>
        <template v-if="tab==='segmentation'||tab==='measurements'"><div class="mw-panel-title">{{tab==='measurements'?'测量工具':'分割工具'}}</div><div class="mw-tool-grid"><button v-for="t in tools" :key="t.id" :class="{active:tool===t.id}" :disabled="props?.readOnly||(!volume||busy||!!interpolationPreview||(!physicalUnitsKnown&&!['navigate','threshold','region','dynamic','cavity','boolean','fill','largest','crop'].includes(t.id)))" @click="chooseTool(t.id)"><b>{{t.icon}}</b>{{t.name}}</button></div><div class="mw-divider"/><div class="mw-panel-title">{{toolName}}</div></template>
        <div v-if="tab==='surface'" class="mw-options">
          <div class="mw-panel-title">Calculate 3D</div><p class="mw-hint">由当前 Mask 生成独立三角表面。</p><label>输入 Mask<strong>{{activeMask?.name||'未选择'}}</strong></label><button class="mw-primary" :disabled="props?.readOnly||(!volume||!state.masks.length||busy)" @click="e.openCalculate3D">Calculate 3D…</button>
          <div class="mw-divider"/><div class="mw-panel-title">表面后处理</div><label class="mw-check"><input v-model="params.keepOriginals" type="checkbox">保留原始模型</label><div class="mw-two"><label>平滑次数<input v-model.number="params.smoothIterations" type="number" min="0" max="100"></label><label>平滑系数<input v-model.number="params.smoothFactor" type="number" min="0" max="1" step=".05"></label></div><label class="mw-check"><input v-model="params.compensate" type="checkbox">补偿体积收缩</label><button :disabled="props?.readOnly||(!activePart||busy)" @click="e.runPart('smooth')">平滑所选表面</button><label>保留三角形比例<input v-model.number="params.reduceRatio" type="number" min=".01" max="1" step=".1"></label><div class="mw-two"><label>容差 mm<input v-model.number="params.tolerance" type="number" min="0" step=".1"></label><label>保边角度 °<input v-model.number="params.featureAngle" type="number" min="0" max="180"></label></div><button :disabled="props?.readOnly||(!activePart||busy)" @click="e.runPart('reduce')">减少三角形</button><div class="mw-divider"/><div class="mw-panel-title">Wrap 包络</div><div class="mw-two"><label>分辨率 mm<input v-model.number="params.wrapResolution" type="number" min=".1" step=".1"></label><label>闭合距离 mm<input v-model.number="params.closingDistance" type="number" min="0" step=".5"></label></div><label class="mw-check"><input v-model="params.protectThinWalls" type="checkbox">保护薄壁</label><button :disabled="props?.readOnly||(!activePart||busy)" @click="e.runPart('wrap')">生成包络表面</button><div class="mw-divider"/><button :disabled="props?.readOnly||(!activePart||busy)" @click="e.runPart('partToMask')">从所选3D计算新 Mask</button><button class="mw-primary" :disabled="(props?.teamMode&&!props?.allowExport)||(!activePart||busy)" @click="e.exportPart">导出 STL</button><AdvancedPanel :tools="e.advanced" :busy="busy||!!props?.readOnly" :has-volume="!!volume" :mask-name="activeMask?.name" :part-name="activePart?.name" surface-only/>
        </div>
        <AdvancedPanel v-else-if="tab==='analysis'" :tools="e.advanced" :busy="busy||!!props?.readOnly" :has-volume="!!volume" :mask-name="activeMask?.name" :part-name="activePart?.name" @tool="tool=$event" @apply-preview="e.applyPreview"/><div v-else class="mw-options">
          <template v-if="tool==='threshold'"><div v-if="volume" class="mw-histogram"><svg viewBox="0 0 288 74" role="img" aria-label="影像灰度直方图"><rect v-for="(v,i) in histogram" :key="i" :x="i*3" :y="72-v" width="2.5" :height="v"/></svg><small>{{format(volume.min)}} <span>{{format(volume.max)}}</span></small></div><div class="mw-two"><label>最小灰度<input v-model.number="params.lower" type="number" :disabled="busy"></label><label>最大灰度<input v-model.number="params.upper" type="number" :disabled="busy"></label></div><template v-if="tool==='threshold'"><label class="mw-check"><input v-model="params.thresholdAutoPreview" type="checkbox" :disabled="busy">自动更新预览</label><label class="mw-check"><input v-model="params.thresholdKeepLargest" type="checkbox" :disabled="busy">Keep largest · 保留最大连通域</label><label class="mw-check"><input v-model="params.thresholdFillHoles" type="checkbox" :disabled="busy">Fill holes · 填充封闭孔洞</label></template><div v-if="tool==='threshold'" class="mw-two"><button :disabled="props?.readOnly||(!activeMask||busy)" @click="e.thresholdPreview">计算预览</button><button :disabled="props?.readOnly||(!preview||busy)" class="mw-primary" @click="e.applyPreview">应用</button></div><p class="mw-hint">包含上下限，仅替换当前 Mask，其他 Mask 保持独立。</p></template>
          <LocalThresholdControls v-if="tool==='local-threshold'" :slot="localThreshold.slot" :ranges="localThreshold.ranges" :disabled="busy" @choose="localThreshold.choose" @update-range="localThreshold.update"/>
          <template v-if="brushSettings"><label>笔刷形状<select v-model="params.brushShape" :disabled="busy||!!interpolationPreview"><option value="circle">Circle / Ellipse · 圆 / 椭圆</option><option value="square">Square / Rectangle · 方 / 矩形</option></select></label><label class="mw-check"><input v-model="params.sameWidthHeight" type="checkbox" :disabled="busy||!!interpolationPreview">Same Width and Height · 宽高相同</label><div class="mw-two" title="宽度沿切片水平物理方向，高度沿垂直物理方向"><label>Width · 宽度 mm<input :value="params.brushWidth" type="number" min=".1" step=".1" :disabled="busy||!!interpolationPreview" @change="changeBrushDimension('width',$event)"></label><label>Height · 高度 mm<input :value="params.brushHeight" type="number" min=".1" step=".1" :disabled="params.sameWidthHeight||busy||!!interpolationPreview" @change="changeBrushDimension('height',$event)"></label></div><label>笔刷直径 / 宽度 {{params.diameter}} mm<input v-model.number="params.diameter" type="range" min="1" max="60" :disabled="busy||!!interpolationPreview"></label><p class="mw-hint">{{multipleEditing?'左键编辑临时选区；最终 Apply 才修改当前 Mask。':'按住左键绘制。单次笔画作为一个可撤销动作。'}}Ctrl + 左键拖动预览笔刷尺寸，松开确定，Esc 取消；Ctrl + 滚轮缩放视图。</p></template>
          <template v-if="['region','dynamic','cavity'].includes(tool)">
            <label v-if="tool==='region'">Source · 源 Mask<select aria-label="区域生长 Source" :value="regionSourceId" :disabled="busy" @change="e.setRegionSource(($event.target as HTMLSelectElement).value)"><option v-for="m in state.masks" :key="m.id" :value="m.id">{{m.name}}</option></select></label>
            <label>{{tool==='region'?'Target · 目标 Mask':'输出'}}<select v-model="params.target" :aria-label="tool==='region'?'区域生长 Target':'生长输出'" :disabled="busy"><option value="new">New Mask · 新建 Mask</option><option v-if="tool!=='region'" value="active">累加到当前 Mask</option><option v-for="m in state.masks.filter(m=>m.id!==(tool==='region'?regionSourceId:state.selectedMaskId))" :key="m.id" :value="m.id">{{m.name}}</option></select></label>
            <button v-if="tool==='region'" :disabled="props?.readOnly||(busy||!regionSource||params.target==='new')" @click="e.swapRegionMasks">⇄ 交换 Source / Target</button>
            <label class="mw-check"><input v-model="params.multiple" type="checkbox" :disabled="busy">Multiple Layer · 跨切片</label><label>连通性<select v-model.number="params.connectivity" :disabled="busy"><option :value="6">6 连通 · 面相邻</option><option :value="26">26 连通 · 面、边、角</option></select></label><label v-if="tool==='region'" class="mw-check"><input v-model="params.leaveOriginal" type="checkbox" :disabled="busy">Leave Original Mask · 保留源成员</label>
            <template v-if="tool==='dynamic'"><div class="mw-two"><label>下偏差<input v-model.number="params.lowerDeviation" type="number" min="0" :disabled="busy"></label><label>上偏差<input v-model.number="params.upperDeviation" type="number" min="0" :disabled="busy"></label></div><label class="mw-check"><input v-model="params.updateMean" type="checkbox" :disabled="busy">随接受体素更新均值</label><label class="mw-check"><input v-model="params.fillCavities" type="checkbox" :disabled="busy">生长后填孔</label></template>
            <p class="mw-seed-hint">⌖ 在{{tool==='region'?' Source Mask 成员内':'影像内'}}点击种子开始{{tool==='cavity'?'填充':'生长'}}。</p><p v-if="tool==='region'" class="mw-hint">点击直接执行；保留源成员时复制，不保留时移动。New 每次生成独立目标；选已有目标可继续累加。新目标不会自动成为活动 Mask。</p><button v-if="tool==='region'" :disabled="props?.readOnly||(busy)" @click="e.closeRegionGrowing">Close · 关闭区域生长</button>
          </template>
          <template v-if="tool==='boolean'"><label>Mask A<strong>{{activeMask?.name||'未选择'}}</strong></label><label>运算<select v-model="params.boolean"><option value="union">并集 A ∪ B</option><option value="intersection">交集 A ∩ B</option><option value="subtract">相减 A − B</option></select></label><label>Mask B<select v-model="params.otherMask"><option value="">选择第二个Mask</option><option v-for="m in state.masks" :key="m.id" :value="m.id">{{m.name}}</option></select></label><button class="mw-primary" :disabled="props?.readOnly||(!activeMask||!params.otherMask||busy)" @click="e.runMask('boolean','布尔运算',{operation:params.boolean})">应用到 Mask A</button></template>
          <template v-if="tool==='morphology'"><label>操作<select v-model="params.morphology"><option value="erode">腐蚀 Erode</option><option value="dilate">膨胀 Dilate</option><option value="open">开操作 Open</option><option value="close">闭操作 Close</option></select></label><label>半径（像素）<input v-model.number="params.radius" type="number" min="0" max="20"></label><label>连接方式<select v-model.number="params.morphConnectivity"><option :value="8">8 · 平面处理</option><option :value="26">26 · 三维处理</option></select></label><button class="mw-primary" :disabled="props?.readOnly||(!activeMask||busy)" @click="e.runMask('morphology','形态学',{operation:params.morphology,radius:params.radius,connectivity:params.morphConnectivity})">应用形态学</button></template>
          <template v-if="tool==='fill'||tool==='largest'"><label class="mw-check"><input v-model="params.multiple" type="checkbox">跨切片处理</label><button class="mw-primary" :disabled="props?.readOnly||(!activeMask||busy)" @click="e.runMask(tool,tool==='fill'?'填充孔洞':'保留最大连通域',planeOptions())">{{tool==='fill'?'填充封闭孔洞':'保留最大连通域'}}</button></template>
          <template v-if="tool==='smartExpand'"><p class="mw-hint">以当前 Mask 为前景种子，在限定距离内按图像灰度扩展。计算后先检查预览。</p><label>最大扩张距离（像素）<input v-model.number="params.maximumExpandDistance" type="number" min="1" max="50" :disabled="busy"></label><label>边缘敏感度<input v-model.number="params.expandSensitivity" type="number" min="0" :disabled="busy"></label><div class="mw-two"><label>最大迭代<input v-model.number="params.expandIterations" type="number" min="1" :disabled="busy"></label><label>前景概率 %<input v-model.number="params.expandProbability" type="number" min="0" max="100" :disabled="busy"></label></div><button class="mw-primary" :disabled="props?.readOnly||(!activeMask||busy)" @click="e.runMask('smartExpand','Smart Expand',{maximumDistance:params.maximumExpandDistance,edgeSensitivity:params.expandSensitivity,maxIterations:params.expandIterations,foregroundPercentage:params.expandProbability,intensityEncoding:'float'},undefined,true)">计算扩展预览</button><button :disabled="props?.readOnly||(!preview||busy)" @click="e.applyPreview">应用扩展</button></template>
          <template v-if="tool==='crop'"><p class="mw-hint">以体素索引设置范围，只裁剪 Mask 成员。</p><div v-for="(a,i) in ['I','J','K']" :key="a" class="mw-two"><label>{{a}} 起点<input v-model.number="params.roiMin[i]" type="number" min="0"></label><label>{{a}} 终点<input v-model.number="params.roiMax[i]" type="number" min="0"></label></div><button :disabled="props?.readOnly||(!activeMask||busy)" class="mw-primary" @click="e.runMask('crop','裁剪Mask',{roi:{min:params.roiMin,max:params.roiMax}})">裁剪当前 Mask</button></template>
          <template v-if="contourTool"><label>Operation<select v-model="params.editOperation" :disabled="busy"><option value="add">Draw · 绘制</option><option value="remove">Erase · 擦除</option><option value="threshold">Threshold · 局部阈值</option></select></label><LocalThresholdControls v-if="params.editOperation==='threshold'" :slot="localThreshold.slot" :ranges="localThreshold.ranges" :disabled="busy" @choose="localThreshold.choose" @update-range="localThreshold.update"/><p v-if="tool==='lasso'" class="mw-hint">按住左键拖动轮廓，松开即按 {{editOperationName}} 修改当前 Mask；Esc 取消本次轮廓。每次闭合为一个可撤销操作。</p><template v-else><label>梯度权重<input v-model.number="params.livewireWeight" type="range" min="0" max="1" step=".05" :disabled="busy"></label><label>吸引<input v-model.number="params.livewireAttraction" type="number" min="-3" max="3" step=".5" :disabled="busy"></label><p class="mw-hint">沿边界点击锚点；双击、Enter 或下方按钮闭合后，直接按 {{editOperationName}} 修改当前 Mask。</p><button :disabled="props?.readOnly||(busy||(mpr.enabled?(mpr.contourDraft?.anchors.length??0)<3:draftPoints.length<3))" @click="e.finishDrawing">闭合轮廓并修改 Mask</button></template><button v-if="mpr.enabled?!!mpr.contourDraft:!!draftPoints.length" @click="e.cancel">取消当前轮廓</button></template>
          <template v-if="multipleEditing">
            <label>编辑方向<select :value="selectionAxis" :disabled="busy||!!interpolationPreview" aria-label="多片编辑方向" @change="e.setSelectionAxis(Number(($event.target as HTMLSelectElement).value) as Axis)"><option v-for="axis in axes" :key="axis" :value="axis">{{selectionDirection(axis)}}</option></select></label>
            <label>Type<select v-model="params.selectionType" :disabled="busy||!!interpolationPreview" aria-label="多片编辑类型"><option value="brush">Brush · 画笔</option><option value="lasso">Lasso · 轮廓</option><option value="livewire">LiveWire</option></select></label>
            <div class="mw-two"><button :class="{active:['select','multiple'].includes(tool)}" :disabled="props?.readOnly||(busy||!!interpolationPreview)" @click="tool='select'">Select · 选择</button><button :class="{active:tool==='deselect'}" :disabled="props?.readOnly||(busy||!!interpolationPreview)" @click="tool='deselect'">Deselect · 取消选择</button></div>
            <p class="mw-hint">只在 {{selectionDirection(selectionAxis)}} 编辑临时选区；其他视图可导航。临时选区 {{format(selectionCount)}} 体素，最终 Apply 前不改变当前 Mask。</p>
            <div class="mw-selection-colors" aria-label="多片编辑颜色说明"><span class="mask-original" :style="{'--original-mask-color':activeMask?.color||'#80a8a0'}">活动 Mask 原色</span><span class="mask-temporary">临时独有 · 紫色</span><span class="mask-overlap">重叠 · 黄色</span></div>
            <p v-if="params.selectionType==='lasso'" class="mw-hint">按住左键绘制轮廓，松开后按 Select / Deselect 修改临时选区。</p>
            <template v-if="params.selectionType==='livewire'"><label>梯度权重<input v-model.number="params.livewireWeight" type="range" min="0" max="1" step=".05" :disabled="busy||!!interpolationPreview"></label><label>吸引<input v-model.number="params.livewireAttraction" type="number" min="-3" max="3" step=".5" :disabled="busy||!!interpolationPreview"></label><p class="mw-hint">沿边界点击锚点，Enter 或下方按钮闭合后修改临时选区。</p><button :disabled="props?.readOnly||(busy||!!interpolationPreview||draftPoints.length<3)" @click="e.finishDrawing">闭合临时选区轮廓</button></template>
            <button v-if="draftPoints.length" :disabled="props?.readOnly||(!!interpolationPreview)" @click="e.cancel">取消当前轮廓</button>
            <label>Copy to slices · 复制层数<input v-model.number="params.copyCount" type="number" min="0" step="1" :disabled="busy||!!interpolationPreview"></label><div class="mw-two"><button :disabled="props?.readOnly||(!selectionCount||busy||!!interpolationPreview)" @click="params.copyDirection=-1;e.copySelection()">−{{['I','J','K'][selectionAxis]}} 方向</button><button :disabled="props?.readOnly||(!selectionCount||busy||!!interpolationPreview)" @click="params.copyDirection=1;e.copySelection()">+{{['I','J','K'][selectionAxis]}} 方向</button></div><small class="mw-hint">0 表示复制到该方向的所有切片；来源是编辑方向的当前层。</small>
            <div class="mw-two"><label>插值起始层<input type="number" min="1" :max="volume?.dims[selectionAxis]||1" :value="params.startSlice+1" :disabled="busy||!!interpolationPreview" @input="params.startSlice=Number(($event.target as HTMLInputElement).value)-1"></label><label>结束层<input type="number" min="1" :max="volume?.dims[selectionAxis]||1" :value="params.endSlice+1" :disabled="busy||!!interpolationPreview" @input="params.endSlice=Number(($event.target as HTMLInputElement).value)-1"></label></div>
            <button :disabled="props?.readOnly||(!selectionCount||busy||!!interpolationPreview)" @click="e.interpolateSelection">预览选区插值</button>
            <div v-if="interpolationPreview" class="mw-interpolation-choice"><p>插值预览尚未替换临时选区。请先接受或取消预览。</p><div class="mw-two"><button :disabled="props?.readOnly||(busy)" @click="e.applyInterpolation">应用插值预览</button><button :disabled="props?.readOnly||(busy)" @click="e.cancelInterpolation">取消插值预览</button></div></div>
            <label>Operation on active mask<select v-model="params.selectionOperation" :disabled="busy||!!interpolationPreview"><option value="add">Draw · 添加</option><option value="remove">Erase · 移除</option><option value="threshold">Threshold · 局部阈值</option></select></label>
            <LocalThresholdControls v-if="params.selectionOperation==='threshold'" :slot="localThreshold.slot" :ranges="localThreshold.ranges" :disabled="busy||!!interpolationPreview" @choose="localThreshold.choose" @update-range="localThreshold.update"/>
            <button class="mw-primary" :disabled="props?.readOnly||(!selectionCount||!activeMask||busy||!!interpolationPreview)" @click="e.applyTemporarySelection">Apply · 应用到活动 Mask</button><div class="mw-two"><button :disabled="props?.readOnly||(busy||!!interpolationPreview)" @click="e.clearSelection">清除临时选区</button><button :disabled="props?.readOnly||(busy||!!interpolationPreview)" @click="e.closeMultipleEdit">Close · 关闭多片编辑</button></div>
          </template>
          <template v-if="densityTool"><div class="mw-panel-title">Density ROI</div><div class="mw-two"><label>Width · 初始宽度 (image px)<input v-model.number="params.densityWidth" type="number" min=".1" step="1" :disabled="busy"></label><label>Height · 初始高度 (image px)<input v-model.number="params.densityHeight" type="number" min=".1" step="1" :disabled="busy"></label></div><p class="mw-hint">点击以初始尺寸放置，或按住左键从起点拖至对角后松开放置。初始 10 × 10 image px 是本应用约定，可修改。</p><p class="mw-hint">{{tool==='density-ellipse'?'四个标记调整椭圆宽高':'边角标记调整矩形宽高'}}；拖动非标记边框整体移动。拖动中只显示轮廓预览，松开后才更新统计；滚动切片随当前层重新统计。</p></template>
          <template v-if="tab==='measurements'">
            <template v-if="tool==='surface-distance'"><p class="mw-hint">在同一个三维表面上依次点击路径约束点，按 Enter 计算沿网格边的路径。</p><button :disabled="props?.readOnly||(draftPoints.length<2||busy)" @click="e.finishDrawing">计算曲面路径</button></template>
            <p v-else-if="tool==='annotation'" class="mw-hint">点击切片或三维对象放置锚点，随后在 Annotation Properties 中编辑并应用；Cancel 不创建注释。</p>
            <template v-else-if="!densityTool">
              <p v-if="tool==='ellipse'" class="mw-seed-hint">依次固定长轴两端，再移动并点击确定短轴。拖动轴端调整大小、中心平移、角点旋转；拖动标签可单独调整文字位置。</p>
              <p v-else-if="tool==='area'" class="mw-seed-hint">在同一切片依次放点，双击或 Enter 闭合。拖动控制点修改轮廓，右击控制点可 Add Point / Remove Point。</p>
              <p v-else class="mw-seed-hint">在切片或三维表面依次放置{{tool==='distance'?'两个':'三个'}}点。</p>
              <span class="mw-hint">已放置 {{draftPoints.length}} 个点</span><button v-if="draftPoints.length" @click="e.cancel">取消当前测量</button>
            </template>
          </template>
          <p v-if="tool==='navigate'" class="mw-hint">左键联动三视图定位；滚轮翻片；Ctrl＋滚轮缩放；右键拖动平移。</p>
          <section v-if="selectedMeasurement&&selectedMeasurement.kind!=='annotation'" class="mw-measurement-details" aria-label="测量数值详情"><div class="mw-divider"/><div class="mw-panel-title">测量详情<span v-if="selectedMeasurementDetails?.preview">拖动预览 · 尚未提交</span></div><strong>{{selectedMeasurement.name}}</strong><p v-if="selectedMeasurementDetails&&!selectedMeasurementDetails.valid" class="mw-hint" role="status">{{selectedMeasurementDetails.reason}}</p><dl><template v-for="row in measurementRows" :key="row.label"><dt>{{row.label}}</dt><dd>{{row.value}}</dd></template></dl><p v-if="selectedMeasurement.kind.startsWith('density')" class="mw-hint">读取当前切片的原始灰度；标准差使用总体定义。采样覆盖面积按有效像素计数，几何面积按 ROI 边界计算。</p></section>
        </div>
      </aside>
    </div>
    <Calculate3DDialog v-if="showCalculate3D" :masks="state.masks" :active-mask-id="state.selectedMaskId" :busy="busy" :progress="progress" :error="error" @calculate="e.calculateParts" @close="e.closeCalculate3D" @cancel="e.cancel"/>
    <MeasurementPropertiesDialog v-if="measurementEditor.draft" :measurement="measurementEditor.draft" :editing-id="measurementEditor.editingId" :busy="busy" @apply="measurementEditor.apply" @cancel="measurementEditor.cancel"/>
    <ReslicePropertiesDialog v-if="reslices.propertiesDraft" :draft="reslices.propertiesDraft" :busy="busy" @apply="reslices.applyProperties" @cancel="reslices.cancelProperties"/>
    <ResliceProjectDialog :open="resliceProject.open" :draft="resliceProject.draft" :preview="resliceProject.preview" :drawing="resliceProject.drawing" :line-point-count="resliceProject.linePoints.length" :busy="busy" :result="resliceProject.summary" :error="resliceProject.error" @update-draft="resliceProject.updateDraft" @draw-line="resliceProject.drawLine" @cancel-line="resliceProject.cancelLine" @use-current-mpr="resliceProject.useCurrentMpr" @preset="resliceProject.preset" @generate="resliceProject.generate" @save-result="resliceProject.saveResult" @download-result="resliceProject.downloadResult" @save-transforms="resliceProject.saveTransforms" @open-result="resliceProject.openResult" @close="resliceProject.close"/>
    <LocalProjectsDialog v-if="showLocalProjects" :projects="localProjects" :busy="busy" :error="cacheError" @close="showLocalProjects=false" @refresh="e.listLocalProjects" @restore="e.restoreLocalProject"/>
    <ReplacementDialog v-if="pendingReplacement" :current-name="state.name" :next-name="pendingReplacement.volume.name" :can-cache="e.cacheAvailable" :busy="busy" :error="error" @choice="e.confirmReplacement"/>
    <footer class="mw-status"><span :class="{error:!!error}">{{status}}</span><span v-if="volume">I {{point[0]}} · J {{point[1]}} · K {{point[2]}}</span><span v-if="volume">{{cacheState==='saved'?'本地副本已保存':cacheState==='pending'?'本地副本保存中':cacheState==='error'?'本地缓存失败':'本地缓存不可用'}}</span><span>本地处理 · {{busy?'正在计算':'就绪'}}</span></footer>
  </div>
</template>
