.mw-mpr-controls{display:flex;flex-direction:column;gap:8px;margin-bottom:12px}.mw-mpr-controls label{display:flex;flex-direction:column;gap:5px;font-size:10px;color:#91a9c5}.mw-mpr-controls button{font-size:10px;padding:6px;white-space:normal;line-height:1.6}.mw-mpr-controls input,.mw-mpr-controls select{width:100%;min-width:0}.mw-mpr-presets,.mw-mpr-angles{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.mw-mpr-controls .mw-hint{margin:3px 0}.mw-mpr-controls .mw-divider{margin:6px 0}
.mw-measurement-details{margin-top:12px}.mw-measurement-details>strong{display:block;font-size:12px;overflow-wrap:anywhere;color:#e0eafa}.mw-measurement-details dl{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:7px 9px;font-size:11px;line-height:1.5;margin:13px 0}.mw-measurement-details dt{color:#a3b8d4}.mw-measurement-details dd{margin:0;text-align:right;color:#e4edf9;font-variant-numeric:tabular-nums;overflow-wrap:anywhere;max-width:145px}
.mw-selection-colors{display:flex;flex-wrap:wrap;gap:4px 9px;font-size:10px;color:#b8cbe0}.mw-selection-colors span::before{content:'';display:inline-block;width:7px;height:7px;border-radius:2px;margin-right:4px;background:#80a8a0}.mw-selection-colors .mask-original::before{background:var(--original-mask-color,#80a8a0)}.mw-selection-colors .mask-temporary::before{background:#b862eb}.mw-selection-colors .mask-overlap::before{background:#ffcd3c}.mw-interpolation-choice{padding:9px;background:#263451;border:1px solid #5b7295;border-radius:4px}.mw-interpolation-choice p{font-size:11px;line-height:1.7;color:#b5cbe6;margin:0 0 8px}
